window.BANK=window.BANK||{};window.BANK["8082"]={"n":"第五章 遵守道德规范 锤炼道德品格","qs":[{"i":"163279","t":"单选","q":"习近平指出：“家庭是社会的基本细胞，是人生的第一所学校。不论时代发生多大变化，不论生活格局发生多大变化，我们都要重视家庭建设，注重家庭、注重家教、注重家风。”以下符合家庭美德的选项有","o":{"A":"A.“远亲不如近邻”","B":"B.“君子成人之美”","C":"C.“为善最乐”","D":"D.“博施济众”"},"a":"A","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P308考点40-2</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>2.大力提倡家庭美德</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">家庭美德以<strong>尊老爱幼、男女平等、夫妻和睦、勤俭持家、邻里互助</strong>为主要内容，在维系和谐美满的婚姻家庭关系中具有重要而独特的功能。</span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>家庭美德的主要内容包括尊老爱幼、男女平等、夫妻和睦、勤俭持家、邻里互助。&ldquo;远亲不如近邻&rdquo;是指邻里互助，A正确。&ldquo;君子成人之美&rdquo;&ldquo;为善最乐&rdquo;&ldquo;博施济众&rdquo;是社会公德中助人为乐的内容，不符合题意，B、C、D错误。</p>","k":"考点31 弘扬家庭美德","kid":"399","r":18760,"tot":29243},{"i":"163280","t":"单选","q":"志愿服务是社会文明进步的重要标志，是新时代党引导动员人民群众贡献智慧力量、创造美好生活、实现奋斗目标的生动实践。志愿服务精神的精髓是","o":{"A":"A.友爱","B":"B.互助","C":"C.进步","D":"D.奉献"},"a":"D","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P308考点41-4-3</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>3参与志愿服务活动。</strong>志愿服务是培育和弘扬社会主义核心价值观的重要载体。志愿服务的精神是奉献、友爱、互助、进步。其中，<strong>奉献精神是精髓。</strong></span></p>\n<p>&nbsp;</p>\n<p><span style=\"color: #000000;\"><strong>简析：</strong>志愿服务是指志愿贡献个人的时间及精力，在不求任何物质报酬的情况下，为改善社会、促进社会进步而提供的服务。志愿服务是培育和弘扬社会主义核心价值观的重要载体。志愿服务的精神是奉献、友爱、互助、进步。其中，奉献精神是精髓。D正确。</span></p>","k":"考点32 锤炼个人品德","kid":"400","r":25452,"tot":27782},{"i":"163281","t":"单选","q":"东汉安帝时，昌邑县令王密为感谢杨震的提聚之恩，夜里怀金十斤馈赠，被杨震拒绝。王密说：“暮夜无知者。”杨震答道：“天知，神知，我知，子知。何谓无知!”王密听后“愧而出”。个人加强道德修养，应借鉴历史上思想家们所提出的各种积极有效的道德修养方法，并结合当今社会发展的需要和当代人道德修养的实践经验，身体力行。这个故事告诉我们，个人加强道德修养，要采取","o":{"A":"A.学思并重的方法","B":"B.省察克治的方法","C":"C.慎独自律的方法","D":"D.积善成德的方法"},"a":"C","j":"<p><span style=\"background-color: #bfedd2;\"><strong>出处：肖老师精讲精练P309考点41表格</strong></span></p>\n<p>&nbsp;</p>\n<p><img src=\"data:image/png;base64,\" alt=\"\" /></p>","k":"考点32 锤炼个人品德","kid":"400","r":19152,"tot":29193},{"i":"163282","t":"单选","q":"“吾日三省吾身”(曾子),这属于中国传统道德修养方法中的","o":{"A":"A.省察克治","B":"B.学思并重","C":"C.慎独自律","D":"D.积善成德"},"a":"A","j":"<p><span style=\"background-color: #bfedd2;\"><strong><span style=\"color: #000000;\">出处：肖老师精讲精练P309考点41表格</span></strong></span></p>\n<p><img src=\"https://cangdun.oss-cn-beijing.aliyuncs.com/cdky/cdkyzz/202607/30/765F2268C78AB9C83274166E6436F921.blob\" alt=\"\" /></p>\n<p><strong>简析：</strong>我国古代思想家们提出了一些积极有效的道德修养方法，包括：①学思并重的方法，即通过虚心学习，积极思索，辨别善恶，学善戒恶，以涵养良好的德性；②省察克治的方法，即通过反省检验以发现和找出自己思想与行为中的不良倾向，并及时进行抑制和克服；3慎独自律的方法，强调在无人知晓或无人监督的情况下，能够对个人内心深处比较隐蔽的意识、情绪进行管理和自律的一种修养方式；4知行合一的方法，即把提高道德认识与躬行道德实践统一起来，以促进道德要求内化为个人的道德品质，外化为实际的道德行为；5积善成德的方法，即通过积累善行或美德，使之巩固强化，以逐渐凝结成优良的品德。A正确。</p>","k":"考点32 锤炼个人品德","kid":"400","r":20123,"tot":29092},{"i":"163283","t":"单选","q":"在社会道德建设中具有基础性作用的是","o":{"A":"A.社会公德","B":"B.职业道德","C":"C.家庭美德","D":"D.个人品德"},"a":"D","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P308考点41-1</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>1.定位</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">个人品德在社会道德建设中具有<strong>基础性作用。</strong>社会公德、职业道德和家庭美德建设，最终都要落实到个人品德的养成上。</span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>个人品德在社会道德建设中具有基础性作用。社会公德、职业道德和家庭美德建设，最终都要落实到个人品德的养成上。无论是社会的和谐有序，还是个人的人格健全，都有赖于个人品德的不断提升。D正确，A、B、C错误。</p>","k":"考点32 锤炼个人品德","kid":"400","r":18711,"tot":29590},{"i":"163284","t":"单选","q":"从业人员在职业活动中做到公平、公正，不损公肥私，不以权谋私，不假公济私，这是职业道德中","o":{"A":"A.爱岗敬业的要求","B":"B.热情服务的要求","C":"C.办事公道的要求","D":"D.奉献社会的要求"},"a":"C","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P307考点39-2</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>2.职业生活中的基本道德规范</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>爱岗敬业、诚实守信、办事公道、热情服务、奉献社会</strong>是职业生活中的基本道德规范。奉献社会是社会主义职业道德中<strong>最高层次的要求</strong>，体现了社会主义职业道德的<strong>最高目标指向。</strong></span></p>\n<p><strong>简析：</strong>职业道德的基本要求包括：①爱岗敬业；②诚实守信；③办事公道，就是要求从业人员做到公平、公正，不损公肥私，不以权谋私，不假公济私；4热情服务；⑤奉献社会。C正确。</p>","k":"考点30 恪守职业道德","kid":"398","r":22103,"tot":28854},{"i":"163285","t":"单选","q":"记者在采访诺贝尔生理学或医学奖得主、中国女药学家屠呦呦时问她：“你在小鼠和猴子身上测试了青蒿素，证明它是有效的之后，你自己也服了药。你害怕吗?”屠呦呦答：“我们担心药物是否安全。我和两位同事服了药，表明药不会死人。我认为这是我作为药物化学家的责任和工作的一部分。”屠呦呦的回答展现了崇高的社会主义职业道德。社会主义职业道德的最高层次的要求是","o":{"A":"A.诚实守信","B":"B.办事公道","C":"C.热情服务","D":"D.奉献社会"},"a":"D","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P307考点39-2</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>2.职业生活中的基本道德规范</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>爱岗敬业、诚实守信、办事公道、热情服务、奉献社会</strong>是职业生活中的基本道德规范。奉献社会是社会主义职业道德中<strong>最高层次的要求</strong>，体现了社会主义职业道德的<strong>最高目标指向。</strong></span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>社会主义职业生活中的基本道德规范包括爱岗敬业、诚实守信、办事公道、热情服务、奉献社会等内容。奉献社会是社会主义职业道德中最高层次的要求，体现了社会主义职业道德的最高目标指向。D正确，A、B、C不符合题意。</p>","k":"考点30 恪守职业道德","kid":"398","r":26193,"tot":27879},{"i":"163286","t":"单选","q":"中华传统美德的根本要求是","o":{"A":"A.以和为贵","B":"B.注重人伦关系","C":"C.追求精神境界，向往理想人格","D":"D.公义胜私欲"},"a":"D","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P305考点35拓展与点拨</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>拓展与点拨：</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">1 在中华传统道德的发展演化中，我们始终强调整体利益、国家利益和民族利益的重要性。传统道德中的义利之辨、理欲之辨，<strong>其核心和本质是</strong>公私之辨。&ldquo;公义胜私欲&rdquo;是中华传统美德的<strong>根本要求。</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">2 推崇仁爱、崇尚和谐是中华民族的<strong>优良传统和高尚品德。</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">3 中华传统美德<strong>一个重要的特点</strong>，就是非常重视每个人在人伦关系中的地位及其价值，强调每个人都必须根据规范的要求来尽自己应尽的义务。</span></p>\n<p>&nbsp;</p>\n<p>&nbsp;</p>","k":"考点27 传承中华传统美德","kid":"395","r":20002,"tot":29231},{"i":"163287","t":"单选","q":"集体主义可以增强一个人恪尽职守、担当任事的责任心，可以激发一个人面对困难和危险不退缩的战斗力，赋予一个人光辉的人格、英雄的风范。集体主义最高层次的道德要求是","o":{"A":"A.先公后私、先人后己","B":"B.顾全大局、遵纪守法","C":"C.无私奉献、一心为公","D":"D.热爱祖国、诚实劳动"},"a":"C","j":"<p><span style=\"color: #000000;\"><strong><span style=\"background-color: #bfedd2;\">出处：肖老师精讲精练P304考点34-3</span></strong></span></p>\n<p><span style=\"color: #000000;\"><strong><span style=\"background-color: #bfedd2;\">3.集体主义的层次性(3个层次)</span></strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">一是无私奉献、一心为公，这是集体主义的<strong>最高层次，</strong>是优秀共产党员、先进分子应努力达到的道德目标。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">二是先公后私、先人后己，这是已经具有较高社会主义道德觉悟的人能够达到的要求。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">三是顾全大局、遵纪守法、热爱祖国、诚实劳动，以正当合法的手段保障个人利益。这是对<strong>公民最基本的道德要求。</strong></span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>根据我国现阶段经济社会生活和人们思想道德的实际，集体主义可分为三个层次的道德要求：一是无私奉献、一心为公，这是集体主义的最高层次，是优秀共产党员、先进分子应努力达到的道德目标。二是先公后私、先人后己，这是已经具有较高社会主义道德觉悟的人能够达到的要求。三是顾全大局、遵纪守法、热爱祖国、诚实劳动，这是对公民最基本的道德要求。C正确。A、B、D不符合题意。</p>","k":"考点26 坚持以集体主义为原则","kid":"394","r":20920,"tot":29359},{"i":"163288","t":"单选","q":"道德具有多方面的功能和效力。通过评价等方式，指导和纠正人们的行为和实践活动、协调社会关系和人际关系的功效与能力，是道德的","o":{"A":"A.认识功能","B":"B.调节功能","C":"C.导向功能","D":"D.规范功能"},"a":"B","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P303考点31-3-(1)-3</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>3 调节功能：</strong>指道德通过评价等方式，指导和纠正人们的行为和实践活动、协调社会关系和人际关系的功效与能力。<strong>道德评价是道德调节的主要形式(通过评价指导和纠正行为)。</strong></span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>在道德的功能系统中，认识功能、规范功能、调节功能是最基本的功能，此外还有导向、激励、教育等功能。道德的调节功能是指道德通过评价等方式，指导和纠正人们的行为和实践活动、协调社会关系和人际关系的功效与能力。B正确。道德的认识功能是指道德反映社会关系特别是反映社会经济关系的功效与能力；道德的规范功能是指在正确善恶观的指引下，规范社会成员在社会公共领域、职业领域、家庭领域的行为，并规范个人品德的养成，引导并促进人们崇德向善。</p>","k":"考点24 坚持马克思主义道德观","kid":"392","r":21025,"tot":29966},{"i":"163289","t":"单选","q":"中国革命道德是指中国共产党人、人民军队、一切先进分子和人民群众在中国革命、建设、改革中所形成的优秀道德，是马克思主义与中国革命、建设、改革的伟大实践相结合的产物，是中华民族极其宝贵的道德财富。中国革命道德的灵魂是","o":{"A":"A.坚持社会主义和共产主义理想信念","B":"B.全心全意为人民服务","C":"C.始终把革命利益放在首位","D":"D.修身自律、保持节操"},"a":"A","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P306考点36-2-1</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>为实现社会主义和共产主义的理想而奋斗。坚持社会主义和共产主义理想信念是革命道德的灵魂。</strong></span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>中国革命道德具有丰富而独特的内涵，既包括革命道德的原则、要求、态度、修养、风尚等方面，也包括革命理想、革命精神等方面，具有丰富的内容。坚持社会主义和共产主义理想信念是革命道德的灵魂。无数革命先烈，正是为了实现这样一个崇高的理想，毫不犹豫地献出了自己的生命。A正确，B、C、D不符合题意。点拨全心全意为人民服务是贯穿中国革命道德始终的一根红线。</p>","k":"考点28 发扬中国革命道德","kid":"396","r":17749,"tot":30536},{"i":"163290","t":"多选","q":"中国革命道德内容丰富、历久弥新，是中国共产党领导全体人民实现民族独立、人民解放的精神支撑，对于我们走好新时代的长征路，实现中华民族伟大复兴仍然具有极其重要的现实意义。中国革命道德的当代价值在于，发扬革命道德、传承红色基因，有利于","o":{"A":"A.加强和巩固社会主义和共产主义的理想信念","B":"B.培育和践行社会主义核心价值观","C":"C.引导人们树立正确的道德观","D":"D.培育良好的社会道德风尚"},"a":"ABCD","j":"<p><strong><span style=\"background-color: #bfedd2; color: #000000;\">出处：肖老师精讲精练P306考点36-3</span></strong></p>\n<p><strong><span style=\"background-color: #bfedd2; color: #000000;\">3.中国革命道德的当代价值(四个有利于)</span></strong></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">①有利于加强和巩固社会主义和共产主义的理想信念。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">②有利于培育和践行社会主义核心价值观。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">③有利于引导人们树立正确的道德观。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">④有利于培育良好的社会道德风尚。</span></p>\n<p>&nbsp;</p>","k":"考点28 发扬中国革命道德","kid":"396","r":24256,"tot":24969},{"i":"163291","t":"多选","q":"中国特色社会主义进入新时代，加强公民道德建设、提高全社会道德水平，具有十分重要的意义。新时代加强公民道德建设，作为着力点的是","o":{"A":"A.社会公德建设","B":"B.职业道德建设","C":"C.家庭美德建设","D":"D.个人品德建设"},"a":"ABCD","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P306考点tips</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>考点tips 38-41</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">新时代公民道德建设要把社会公德、职业道德、家庭美德、个人品德建设作为<strong>着力点</strong>。<strong>重点任务是</strong>：筑牢理想信念之基，培育和践行社会主义核心价值观，传承中华传统美德，弘扬民族精神和时代精神。</span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>中共中央、国务院印发的《新时代公民道德建设实施纲要》指出，新时代公民道德建设要把社会公德、职业道德、家庭美德、个人品德建设作为着力点。A、B、C、D全选。</p>","k":"考点29 遵守社会公德","kid":"397","r":21820,"tot":25573},{"i":"163292","t":"多选","q":"新时代公民道德建设的重点任务是","o":{"A":"A.筑牢理想信念之基","B":"B.培育和践行社会主义核心价值观","C":"C.传承中华传统美德","D":"D.弘扬民族精神和时代精神"},"a":"ABCD","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P306考点tips</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>考点tips 38-41</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">新时代公民道德建设要把社会公德、职业道德、家庭美德、个人品德建设作为<strong>着力点</strong>。<strong>重点任务是</strong>：筑牢理想信念之基，培育和践行社会主义核心价值观，传承中华传统美德，弘扬民族精神和时代精神。</span></p>","k":"考点29 遵守社会公德","kid":"397","r":22802,"tot":25446},{"i":"163293","t":"多选","q":"当代公共生活的特征主要表现在","o":{"A":"A.活动范围的广泛性","B":"B.活动内容的开放性","C":"C.交往对象的复杂性","D":"D.活动方式的多样性"},"a":"ABCD","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P306考点38-1-1</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>当代公共生活的特征：一是</strong>活动范围的广泛性；<strong>二是</strong>活动内容的开放性；<strong>三是</strong>交往对象的复杂性；<strong>四是</strong>活动方式的多样性。</span></p>\n<p>&nbsp;</p>","k":"考点29 遵守社会公德","kid":"397","r":22695,"tot":25407},{"i":"163294","t":"多选","q":"网络空间同现实社会一样，既要提倡自由，也要保持秩序。公共生活需要公共秩序，有序的公共生活是","o":{"A":"A.调整和规范人际关系的行为准则","B":"B.社会生产活动的重要基础","C":"C.提高社会成员生活质量的基本保障","D":"D.社会文明的重要标志"},"a":"BCD","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P306考点38-1-2</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>公共生活需要公共秩序。</strong>有序的公共生活是<strong>社会生产活动的重要基础</strong>；是<strong>提高社会成员生活质量的基本保障</strong>；更是<strong>社会文明的重要标志。</strong></span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>公共秩序是由一定规范维系的人们公共生活的一种有序化状态。公共生活领域越扩大，对公共生活秩序的要求就越高。在当代社会，维护公共秩序对经济社会健康发展的重要意义愈加突出。有序的公共生活是社会生产活动的重要基础，是提高社会成员生活质量的基本保障，更是社会文明的重要标志。B、C、D正确。文明礼貌是调整和规范人际关系的行为准则，A错误。</p>","k":"考点29 遵守社会公德","kid":"397","r":8756,"tot":30253},{"i":"163295","t":"多选","q":"公共生活中的道德规范即社会公德。以下对社会公德理解正确的有","o":{"A":"A.社会公德是指人们在社会交往和公共生活中应该遵守的行为准则","B":"B.遵纪守法是全体公民都必须遵循的基本行为准则","C":"C.社会公德是维护公共利益、公共秩序、社会和谐稳定的起码的道德要求","D":"D.社会公德的最高层次的要求是奉献社会"},"a":"ABC","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P307考点38-2</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>2.公共生活中的道德规范(社会公德)</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>社会公德是维护公共利益、公共秩序、社会和谐稳定的起码的道德要求</strong>，涵盖了人与人、人与社会、人与自然之间的关系。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">①<strong>文明礼貌</strong>(调整和规范人际关系的行为准则)。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">②<strong>助人为乐。</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">③<strong>爱护公物</strong>(既显示出个人的道德修养水平，也是社会文明水平的重要标志)。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">④<strong>保护环境。</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">⑤<strong>遵纪守法</strong>(全体公民都必须遵循的基本行为准则，维护公共生活秩序的重要条件)。</span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>A、B、C正确。奉献社会是社会主义职业道德中最高层次的要求，D错误。</p>","k":"考点29 遵守社会公德","kid":"397","r":9899,"tot":29078},{"i":"163296","t":"多选","q":"网络生活中的道德要求，是人们在网络生活中为了维护正常的网络公共秩序而需要共同遵守的基本道德准则，是社会公德在网络空间的运用和扩展。网络生活中的道德要求有","o":{"A":"A.正确使用网络工具","B":"B.加强网络文明自律","C":"C.进行健康网络交往","D":"D.营造良好网络道德环境"},"a":"ABCD","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P307考点38-3</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>3.网络生活中的道德要求</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">从本质上说，网络交往仍然是人与人的现实交往，网络生活也是人的真实生活，因而也必须遵守道德规范。<strong>网络生活中的道德要求是社会公德在网络空间的运用和扩展。</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">①<strong>正确使用网络工具。</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">②<strong>加强网络文明自律。要做到：</strong>进行健康网络交往；自觉避免沉迷网络；加强网络道德自律。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">③<strong>营造良好网络道德环境。</strong></span></p>\n<p>&nbsp;</p>","k":"考点29 遵守社会公德","kid":"397","r":23828,"tot":24874},{"i":"163297","t":"多选","q":"职业道德中的诚实守信，要求从业者在职业活动中","o":{"A":"A.诚实劳动","B":"B.合法经营","C":"C.信守承诺","D":"D.讲求信誉"},"a":"ABCD","j":"考点拓展题","k":"考点30 恪守职业道德","kid":"398","r":22955,"tot":24905},{"i":"163298","t":"多选","q":"“怒发冲冠，凭栏处、潇潇雨歇。”抗金名将岳飞留给我们的，除了气吞山河的壮烈，莫须冤死的悲戚，还有一段精忠报国的热血家训。习近平曾多次讲过岳母刺字的故事，强调家风是社会风气的重要组成部分，父母应引导孩子成为对国家和人民有用的人。之所以要注重家教、家风，是因为","o":{"A":"A.家庭是人生的第一个课堂，父母是孩子的第一任老师","B":"B.良好的家风，对家庭成员的个人修养产生着重要的作用","C":"C.良好的家风，对整个社会道德风尚的形成产生着重要的影响","D":"D.家教是新时代公民道德建设的重点任务"},"a":"ABC","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P308考点40-1-3</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>注重家风。</strong>家风是指一个家庭或家族世代相传的风尚、作风，即一个家庭当中的风气。家风是社会风气的重要组成部分。<strong>良好的家风，对家庭成员的个人修养产生着重要的作用，也对整个社会道德风尚的形成产生着重要的影响。</strong></span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>A、B、C正确。新时代公民道德建设的重点任务是筑牢理想信念之基、培育和践行社会主义核心价值观、传承中华传统美德、弘扬民族精神和时代精神。D错误。</p>","k":"考点31 弘扬家庭美德","kid":"399","r":12895,"tot":27893},{"i":"163299","t":"多选","q":"为深入学习贯彻习近平总书记关于注重家庭家教家风建设的重要论述，中央宣传部、全国妇联于2026年5月向全社会发布2026年“最美家庭”,10户家庭光荣入选2026年“最美家庭”。家是最小国，国是千万家，家庭的命运同国家和民族的前途命运紧密相连，要以“最美家庭”为榜样，大力弘扬社会主义家庭文明新风尚。社会主义家庭文明新风尚的内容是","o":{"A":"A.爱国爱家","B":"B.相亲相爱","C":"C.向上向善","D":"D.共建共享"},"a":"ABCD","j":"<p>时政储备题</p>\n<p><strong>简析：</strong>当代青年作为家庭的重要成员，也要积极弘扬践行家庭美德，感念父母养育之恩，感念长辈关爱之情，孝敬父母、尊重长辈、回报家庭、回馈社会，推动形成爱国爱家、相亲相爱、向上向善、共建共享的社会主义家庭文明新风尚。A、B、C、D全选。</p>","k":"考点31 弘扬家庭美德","kid":"399","r":16883,"tot":26745},{"i":"163300","t":"多选","q":"在2025年五四青年节到来之际，习近平给新疆克孜勒苏柯尔克孜自治州阿图什市哈拉峻乡谢依特小学戍边支教西部计划志愿者服务队全体队员回信。回信指出，这些年，越来越多年轻人选择到西部、到乡村、到基层志愿服务，无私奉献，展现了新时代中国青年昂扬向上的精神风貌和强国有我的责任担当。志愿服务","o":{"A":"A.是培育和弘扬社会主义核心价值观的重要载体","B":"B.已经成为衡量地区社会文明程度、社会治理水平的根本标准","C":"C.归根结底是一种先进文化现象","D":"D.已成为大学生参与社会实践、成长成才的重要舞台"},"a":"ACD","j":"<p>考点拓展题</p>\n<p><strong>简析：</strong>志愿服务是培育和弘扬社会主义核心价值观的重要载体。志愿服务的精神是奉献、友爱、互助、进步。其中，奉献精神是精髓。当前，志愿服务已经成为大学生参与社会实践、成长成才的重要舞台，成为大学生关爱他人、传播青春正能量的重要途径。大学生志愿服务活动已经遍及农村扶贫开发、城市社区建设、环境保护、大型活动、抢险救灾、社会公益等领域。A、D正确。</p>\n<p>《关于健全新时代志愿服务体系的意见》提出，到2035年，&ldquo;志愿服务成为社会主义文化强国的重要标志&rdquo;。一个民族的复兴需要强大的物质力量，也需要强大的精神力量。志愿服务归根结底是一种先进文化现象，志愿精神必将成为中国特色社会主义文化的高尚元素，引领和推动中国特色志愿服务在新征程的新发展。C正确。</p>\n<p>衡量社会文明程度与社会治理水平需要综合考量，志愿服务不能作为其&ldquo;根本标准&rdquo;。B错误。</p>","k":"考点32 锤炼个人品德","kid":"400","r":19963,"tot":25811},{"i":"163301","t":"多选","q":"加强社会主义道德建设必须吸收借鉴优秀道德成果，传承中华传统美德。中华传统美德","o":{"A":"A.是中华文化的精髓","B":"B.蕴含着丰富的思想道德资源","C":"C.是社会主义道德建设的源头活水","D":"D.是人类文明发展的重要精神财富"},"a":"ABCD","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P304考点35-1</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>1.传承中华传统美德的重要性</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">中华传统美德是中华文化的<strong>精髓</strong>，蕴含着丰富的思想道德资源；是社会主义道德建设的<strong>源头活水</strong>；是人类文明发展的<strong>重要精神财富</strong>。</span></p>\n<p>&nbsp;</p>","k":"考点27 传承中华传统美德","kid":"395","r":21030,"tot":26313},{"i":"163302","t":"多选","q":"2024年10月，习近平在福建省漳州市东山县考察时，来到谷文昌纪念馆，强调“学习谷文昌同志，不仅要高山仰止，还要见贤思齐，像他那样做人、为政”。“见贤思齐”是中华传统美德中强调道德修养，注重道德践履的体现。中国古代的思想家大都认为，在修身养性的过程中，最重要的就是要使社会的道德原则和规范转换为自身的思想品德和行为实践，通过切磋践履不断养成良好的道德习惯，形成完善的道德人格。以下选项中，体现了中华传统美德强调道德修养，注重道德践履的有","o":{"A":"A.“修己”“克己”和“慎独”","B":"B.“善养吾浩然之气”","C":"C.“明于庶物，察于人伦”","D":"D.“察色修身”"},"a":"ABD","j":"<p><strong><span style=\"background-color: #bfedd2; color: #000000;\">出处：肖老师精讲精练P305考点35表格</span></strong></p>\n<p><img src=\"assets/images/B037393EC99211C0E0455BE4411EF343.png\" /></p>\n<p><strong>简析：</strong>中国古代的思想家大都认为，在修身养性的过程中，最重要的就是要使社会的道德原则和规范转换为自身的思想品德和行为实践，通过切磋践履不断养成良好的道德习惯，形成完善的道德人格。儒家经典《礼记》中明确提出，&ldquo;修身&rdquo;是&ldquo;齐家、治国、平天下&rdquo;的前提和基础，孔子提倡&ldquo;修己&rdquo;&ldquo;克己&rdquo;和&ldquo;慎独&rdquo;,提倡&ldquo;见贤思齐焉，见不贤而内自省也&rdquo;,孟子更主张&ldquo;善养吾浩然之气&rdquo;。墨家也非常重视修身，强调&ldquo;察色修身&rdquo;和&ldquo;以身戴行&rdquo;。这些都是强调道德修养，注重道德践履的体现。A、B、D正确。&ldquo;明于庶物，察于人伦&rdquo;属于追求精神境界，向往理想人格的内容，不符合题意。C错误。</p>","k":"考点27 传承中华传统美德","kid":"395","r":10908,"tot":28914},{"i":"163303","t":"多选","q":"2024年10月17日，习近平来到安徽省安庆桐城市考察。地处城中的六尺巷，因清代大学士张英与邻居吴家互相退让三尺地基而成，是中国邻里和谐礼让的典范。习近平指出，人民内部矛盾要用调解的办法解决。六尺巷体现了先人化解矛盾的历史智慧，要作为弘扬中华优秀传统文化的教育场所，发挥好中华民族讲求礼让、以和为贵传统美德的作用，营造安居乐业的和谐社会环境。推崇仁爱、崇尚和谐是中华民族的优良传统和高尚品德。以下选项中，体现了中华传统美德推崇仁爱原则，注重以和为贵的有","o":{"A":"A.“己欲立而立人，己欲达而达人”","B":"B.“亲亲而仁民，仁民而爱物”","C":"C.“仁、义、礼、智、信”","D":"D.“兼相爱，交相利”"},"a":"ABD","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P305考点35表格</strong></span></p>\n<p><strong><img src=\"assets/images/B1B09A442E566AF7DFB9756EF54AF855.png\" /></strong></p>\n<p>&nbsp;</p>\n<p><strong>简析</strong>：A、B、D正确。&ldquo;仁、义、礼、智、信&rdquo;属于中华传统美德中注重人伦关系，重视道德义务的内容，C错误。</p>","k":"考点27 传承中华传统美德","kid":"395","r":10838,"tot":28676},{"i":"163304","t":"多选","q":"作为社会意识的道德一经产生，便有相对独立性。这种相对独立性表现为","o":{"A":"A.道德的历史继承性","B":"B.道德对社会发展具有能动的反作用","C":"C.在阶级社会里道德具有阶级性","D":"D.道德随着社会经济关系的变化而变化"},"a":"AB","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P302考点31-2-①</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>道德是反映社会经济关系的特殊意识形态。道德的产生、发展和变化，归根结底源于社会经济关系。首先，</strong>道德的性质和基本原则、规范反映了与之相应的社会经济关系的性质和内容。<strong>其次，</strong>道德随着社会经济关系的变化而变化。<strong>再次，</strong>道德作为一种社会意识，在阶级社会里总是反映着一定阶级的利益，因而不可避免地具有阶级性。同时，不同阶级之间的道德或多或少有一些共同之处，反映着道德的普遍性。<strong>最后，道德作为社会意识一经产生，便有相对独立性</strong>(表现为道德的历史继承性和对社会发展具有能动的反作用)。</span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>作为社会意识的道德一经产生，便有相对独立性。这种相对独立性既表现为道德的历史继承性，也表现为道德对社会发展具有能动的反作用，A、B正确。C、D内容正确但不符合题意。</p>","k":"考点24 坚持马克思主义道德观","kid":"392","r":9494,"tot":31460},{"i":"163305","t":"多选","q":"道德属于上层建筑的范畴，是一种特殊的社会意识形态。道德以善恶为评价方式，发挥作用主要是依靠","o":{"A":"A.社会舆论","B":"B.传统习俗","C":"C.内心信念","D":"D.国家强制"},"a":"ABC","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P302 考点31坚持马克思主义道德观&mdash;&mdash;道德的起源、本质、功能与作用</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">道德属于上层建筑的范畴，是一种特殊的社会意识形态。它是以善恶为评价方式，主要依靠<strong>社会舆论、传统习俗和内心信念</strong>来发挥作用的行为规范的总和。道德是立身兴国之本，对个人和社会都具有基础性意义。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>1.道德的起源</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">①<strong>劳动</strong>是道德起源的<strong>首要前提</strong>。道德是人类社会的特有现象。劳动创造了人和人类社会，是道德起源的<strong>第一个历史前提。</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">②<strong>社会关系</strong>是道德赖以产生的<strong>客观条件。</strong>道德正是适应社会关系尤其是利益关系调节的需要而产生的。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">③<strong>人的自我意识</strong>是道德产生的<strong>主观条件</strong>。意识是道德产生的<strong>思想认识前提。</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>2.道德的本质</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">①<strong>道德是反映社会经济关系的特殊意识形态。道德的产生、发展和变化，归根结底源于社会经济关系。首先，</strong>道德的性质和基本原则、规范反映了与之相应的社会经济关系的性质和内容。<strong>其次，</strong>道德随着社会经济关系的变化而变化。<strong>再次，</strong>道德作为一种社会意识，在阶级社会里总是反映着一定阶级的利益，因而不可避免地具有阶级性。同时，不同阶级之间的道德或多或少有一些共同之处，反映着道德的普遍性。<strong>最后，道德作为社会意识一经产生，便有相对独立性</strong>(表现为道德的历史继承性和对社会发展具有能动的反作用)。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">②<strong>道德是社会利益关系的特殊调节方式。</strong>道德是一种调整人与人、人与社会、人与自然以及人与自身之间关系的特殊的行为规范。<strong>道德与法律规范、政治规范的不同之处在于，它是用善恶标准去评价，依靠社会舆论、传统习俗、内心信念来维持的，因此是一种非强制性的规范。</strong>道德是处于同一社会或同一生活环境中的人们在长期的共同生活过程中逐渐积累形成的要求、秩序和理想，<strong>它通过社会的道德风尚和个人的道德风范来调节利益关系。</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">③<strong>道德是一种实践精神，在本质上是知行合一的。</strong>道德立足现实而追求理想，并以理想来改造和提升现实。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>3.道德的功能与作用</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>(1)道德的功能</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">道德最基本的功能是<strong>认识功能、规范功能和调节功能</strong>，此外还有导向、激励、教育等功能。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">①<strong>认识功能：</strong>指道德反映社会关系特别是反映社会经济关系的功效与能力。道德往往运用善恶、荣辱、义务、良心等范畴，反映人类的道德实践活动和道德关系，从中揭示社会道德发展的趋势，为人们的行为选择提供指南。尤其是在日常生活中，人们正是借助道德认识自己对他人、家庭、社会的道德义务和责任，<strong>使人们的道德选择、道德行为建立在明辨善恶的道德认识基础上，从而正确选择自己的道德行为，</strong>积极塑造自身的良好道德品质。<strong>(选择道德行为)</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">②<strong>规范功能：</strong>指在正确善恶观的指引下，规范社会成员在社会公共领域、职业领城、家庭领域的行为，并规范个人品德的养成，引导并促进人们崇德向善(规范行为)。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">③<strong>调节功能：</strong>指道德通过评价等方式，指导和纠正人们的行为和实践活动、协调社会关系和人际关系的功效与能力。<strong>道德评价是道德调节的主要形式(通过评价指导和纠正行为)。</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>(2)道德的作用(立身兴国之本，对个人和社会都具有基础性意义)</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">①道德作为维系社会稳定、促进国家发展的重要因素，对巩固特定社会的经济基础和上层建筑具有不可替代的重要作用。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">②道德作为激励人们改造客观世界和主观世界的一种精神力量，是提高人的精神境界、促进人的自我完善、推动人的全面发展的内在动力。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">在道德的作用问题上，要反对两种极端的看法，即&ldquo;道德万能论&rdquo;和&ldquo;道德无用论&rdquo;。</span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>道德属于上层建筑的范畴，是一种特殊的社会意识形态。道德是以善恶为评价方式，主要依靠社会舆论、传统习俗和内心信念来发挥作用的行为规范的总和。A、B、C正确。国家强制性是法律规范区别于其他社会规范的一个重要特征。作为一种调整人与人、人与社会、人与自然以及人与自身之间关系的特殊的行为规范，道德与法律规范、政治规范的不同之处在于，它是一种非强制性的规范。D错误。</p>\n<p><strong>点拨：</strong>道德的调节功能是指道德通过评价等方式指导和纠正人们的行为和实践活动、协调社会关系和人际关系的功效与能力。道德评价是道德调节的主要形式，社会舆论、传统习俗和人们的内心信念是道德调节所赖以发挥作用的力量。</p>","k":"考点24 坚持马克思主义道德观","kid":"392","r":21638,"tot":27279},{"i":"163306","t":"多选","q":"道德的功能，一般是指道德作为社会意识的特殊形式对于社会发展所具有的功效与作用。在道德的功能系统中，最基本的功能是","o":{"A":"A.认识功能","B":"B.规范功能","C":"C.调节功能","D":"D.表达功能"},"a":"ABC","j":"<p><strong><span style=\"background-color: #bfedd2; color: #000000;\">出处：肖老师精讲精练P302考点31-3-(1)</span></strong></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>(1)道德的功能</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">道德最基本的功能是<strong>认识功能、规范功能和调节功能</strong>，此外还有导向、激励、教育等功能。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">①<strong>认识功能：</strong>指道德反映社会关系特别是反映社会经济关系的功效与能力。道德往往运用善恶、荣辱、义务、良心等范畴，反映人类的道德实践活动和道德关系，从中揭示社会道德发展的趋势，为人们的行为选择提供指南。尤其是在日常生活中，人们正是借助道德认识自己对他人、家庭、社会的道德义务和责任，<strong>使人们的道德选择、道德行为建立在明辨善恶的道德认识基础上，从而正确选择自己的道德行为，</strong>积极塑造自身的良好道德品质。<strong>(选择道德行为)</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">②<strong>规范功能：</strong>指在正确善恶观的指引下，规范社会成员在社会公共领域、职业领城、家庭领域的行为，并规范个人品德的养成，引导并促进人们崇德向善(规范行为)。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">③<strong>调节功能：</strong>指道德通过评价等方式，指导和纠正人们的行为和实践活动、协调社会关系和人际关系的功效与能力。<strong>道德评价是道德调节的主要形式(通过评价指导和纠正行为)。</strong></span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>道德的功能，一般是指道德作为社会意识的特殊形式对于社会发展所具有的功效与作用。在道德的功能系统中，最基本的功能是认识功能、规范功能和调节功能。A、B、C正确，D错误。</p>","k":"考点24 坚持马克思主义道德观","kid":"392","r":18935,"tot":27715},{"i":"163307","t":"多选","q":"道德功能的发挥和实现所产生的社会影响及实际效果，就是道德的作用。道德的作用主要表现在","o":{"A":"A.巩固特定社会的经济基础和上层建筑","B":"B.提高人的精神境界","C":"C.促进人的自我完善","D":"D.推动人的全面发展"},"a":"ABCD","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P303考点31-3-(2)</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>(2)道德的作用(立身兴国之本，对个人和社会都具有基础性意义)</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">①道德作为维系社会稳定、促进国家发展的重要因素，对巩固特定社会的经济基础和上层建筑具有不可替代的重要作用。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">②道德作为激励人们改造客观世界和主观世界的一种精神力量，是提高人的精神境界、促进人的自我完善、推动人的全面发展的内在动力。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">在道德的作用问题上，要反对两种极端的看法，即&ldquo;道德万能论&rdquo;和&ldquo;道德无用论&rdquo;。</span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>道德作用的主要表现是：道德作为维系社会稳定、促进国家发展的重要因素，对巩固特定社会的经济基础和上层建筑具有不可替代的重要作用。2道德作为激励人们改造客观世界和主观世界的一种精神力量，是提高人的精神境界、促进人的自我完善、推动人的全面发展的内在动力。A、B、C、D全选。</p>","k":"考点24 坚持马克思主义道德观","kid":"392","r":18857,"tot":27785}]};
